enum WaveStageEnum {
    WAVE_StageBuilding,
    WAVE_StageStable,
    WAVE_StageSubsiding,
    WAVE_StageMax
};

enum WavePerturbStageEnum {
    WAVE_PerturbStageNone
};

enum WavePerturbTypeEnum {
    WAVE_PerturbTypeDummy
};

struct WaveBreakInfoStruct {
    bool onoff;
    WavePerturbTypeEnum type;
    float time;
    WavePerturbStageEnum stage;
    float stageprogress;
};

extern float WAVE_StageStart[WAVE_StageMax];
extern float WAVE_StageDuration[WAVE_StageMax];
extern float WAVE_TotalSec;
extern float WAVE_ScaleU;
extern float WAVE_ScaleV;
extern float WAVE_ShiftU;
extern float WAVE_ShiftV;
extern float WAVE_ShiftX;
extern float WAVE_ShiftZ;
extern float WAVE_ShiftSpeedU;
extern float WAVE_ShiftSpeedV;
extern float WAVE_ScheduleTimeStart;
extern float WAVE_ScheduleTimeEnd;
extern WaveStageEnum WAVE_Stage;
extern WavePerturbStageEnum WAVE_PerturbStage;
extern bool particle_enable;
extern WaveBreakInfoStruct WAVE_BreakInfo;

void WAVE_ComputeGrid(void);
void WAVE_ComputeShift(void);
void WAVE_ComputeStage(void);
void WAVE_ComputeVTwist(void);
void WAVE_ComputeSlices(void);
void WAVE_EmitterUpdate(void);
void WAVE_SoundUpdate(void);
void ks_fx_update(void);
void WAVE_GetBreakInfo(WaveBreakInfoStruct *);

class KSWaterState
{
    float StageStart[WAVE_StageMax];
    float StageDuration[WAVE_StageMax];
    float ScaleU;
    float ScaleV;
    float ShiftU;
    float ShiftV;
    float ShiftX;
    float ShiftZ;
    float ShiftSpeedU;
    float ShiftSpeedV;
    int Stage;
    int PerturbStage;
    float ScheduleTimeStart;
    float ScheduleTimeEnd;
    float TotalSec;

public:
    void Restore(void);
};

void KSWaterState::Restore(void)
{
  for(int i=0; i<WAVE_StageMax; i++)
  {
    WAVE_StageStart[i] = StageStart[i];
    WAVE_StageDuration[i] = StageDuration[i];
  }
    WAVE_TotalSec = TotalSec;
    WAVE_ScaleU=ScaleU;
    WAVE_ScaleV=ScaleV;
    WAVE_ShiftU=ShiftU;
    WAVE_ShiftV=ShiftV;
    WAVE_ShiftX=ShiftX;
    WAVE_ShiftZ=ShiftZ;
    WAVE_ShiftSpeedU = ShiftSpeedU;
    WAVE_ShiftSpeedV = ShiftSpeedV;
    WAVE_ScheduleTimeStart = ScheduleTimeStart;
    WAVE_ScheduleTimeEnd = ScheduleTimeEnd;
    WAVE_Stage=(WaveStageEnum) Stage;
    WAVE_PerturbStage = (WavePerturbStageEnum) PerturbStage;
    WAVE_ComputeGrid();
    WAVE_ComputeShift();
    WAVE_ComputeStage();
    WAVE_ComputeVTwist();
    WAVE_ComputeSlices();
    WAVE_EmitterUpdate();
    WAVE_SoundUpdate();
    if ( particle_enable )
    {
      ks_fx_update();
    }
    WAVE_GetBreakInfo(&WAVE_BreakInfo);
}
